-- 字段说明按型号写清读数和写入。井盖远程是 0，风机和井盖的开关不跟照明、水泵共用一句说明。
-- 点位表写明舱室的点，改挂到该防火区下面的舱室。描述里没有舱室的井盖和配电柜，仍挂在防火区。
-- 点位编码不动。

SET search_path TO dynamicbusiness, public;

INSERT INTO dynamicbusiness.dynamic_field (
    code, name, type, description, source, status, creator, updater,
    deleted, tenant_id, governance_status
)
SELECT v.code, v.name, 'BOOLEAN', v.description, 'CUSTOM', 1,
       'point-table-seed', 'point-table-seed', false, 123, 'COMPANY'
FROM (VALUES
    ('F-a11c0e0000014e0a8f0e00000000c001', '远程', '处于远程时为 0，平台可以控制。为 1 时不在远程，平台不能控制。这是状态，不是开关命令。'),
    ('F-a11c0e0000014e0a8f0e00000000c002', '开', '开风机时向这个标签写 1。持续 1 秒的脉冲由 PLC 完成。平台不把这个标签写回 0。'),
    ('F-a11c0e0000014e0a8f0e00000000c003', '开', '打开时这个标签保持为 1，同时关标签写成 0。关闭时这个标签写成 0，同时关标签写成 1。两个标签在同一时刻相反。'),
    ('F-a11c0e0000014e0a8f0e00000000c004', '关', '关风机时向这个标签写 1。持续 1 秒的脉冲由 PLC 完成。平台不把这个标签写回 0。'),
    ('F-a11c0e0000014e0a8f0e00000000c005', '关', '关闭时这个标签为 1，同时开标签写成 0。打开时这个标签写成 0，同时开标签保持为 1。两个标签在同一时刻相反。')
) AS v(code, name, description)
WHERE NOT EXISTS (
    SELECT 1 FROM dynamicbusiness.dynamic_field existing
    WHERE existing.tenant_id = 123 AND existing.deleted = false AND existing.code = v.code
);

INSERT INTO dynamicbusiness.dynamic_model_field_assignment (
    model_id, field_id, required, is_searchable, is_filterable, is_sortable, sort,
    creator, updater, deleted, tenant_id, model_code, field_code, collection_point,
    create_visible, edit_visible, detail_visible, field_source
)
SELECT
    model.id, field.id, false, false, false, false, source.sort,
    'point-table-seed', 'point-table-seed', false, 123,
    model.code, field.code, true, false, false, false, 'USER_ADDED'
FROM (VALUES
    (2595, 'F-a11c0e0000014e0a8f0e00000000c001', 'F-f37cd202f4da46558cf5a48a05fd0a4a'),
    (2593, 'F-a11c0e0000014e0a8f0e00000000c002', 'F-ab068b1dd098457cba93ad89cf095f90'),
    (2595, 'F-a11c0e0000014e0a8f0e00000000c003', 'F-ab068b1dd098457cba93ad89cf095f90'),
    (2593, 'F-a11c0e0000014e0a8f0e00000000c004', 'F-0f1f5c4d0e6d4cdd84733f17637a9c04'),
    (2595, 'F-a11c0e0000014e0a8f0e00000000c005', 'F-0f1f5c4d0e6d4cdd84733f17637a9c04')
) AS plan(model_id, new_code, old_code)
JOIN dynamicbusiness.dynamic_model model
  ON model.id = plan.model_id AND model.deleted = false
JOIN dynamicbusiness.dynamic_field field
  ON field.tenant_id = 123 AND field.deleted = false AND field.code = plan.new_code
JOIN dynamicbusiness.dynamic_model_field_assignment source
  ON source.tenant_id = 123 AND source.deleted = false
 AND source.model_id = plan.model_id AND source.field_code = plan.old_code
WHERE NOT EXISTS (
    SELECT 1 FROM dynamicbusiness.dynamic_model_field_assignment existing
    WHERE existing.tenant_id = 123 AND existing.deleted = false
      AND existing.model_id = plan.model_id AND existing.field_code = plan.new_code
);

UPDATE dynamicbusiness.ent_point_binding_t123 point
SET point_field_code = plan.new_code,
    updater = 'point-table-seed',
    update_time = CURRENT_TIMESTAMP
FROM dynamicbusiness.ent_equipment_t123 equipment,
     (VALUES
        (2595, 'F-f37cd202f4da46558cf5a48a05fd0a4a', 'F-a11c0e0000014e0a8f0e00000000c001'),
        (2593, 'F-ab068b1dd098457cba93ad89cf095f90', 'F-a11c0e0000014e0a8f0e00000000c002'),
        (2595, 'F-ab068b1dd098457cba93ad89cf095f90', 'F-a11c0e0000014e0a8f0e00000000c003'),
        (2593, 'F-0f1f5c4d0e6d4cdd84733f17637a9c04', 'F-a11c0e0000014e0a8f0e00000000c004'),
        (2595, 'F-0f1f5c4d0e6d4cdd84733f17637a9c04', 'F-a11c0e0000014e0a8f0e00000000c005')
     ) AS plan(model_id, old_code, new_code)
WHERE equipment.id = point.equipment_id
  AND equipment.deleted = false
  AND equipment.model_id = plan.model_id
  AND point.tenant_id = 123
  AND point.deleted = false
  AND point.point_field_code = plan.old_code;

UPDATE dynamicbusiness.dynamic_model_field_assignment assignment
SET deleted = true,
    updater = 'point-table-seed',
    update_time = CURRENT_TIMESTAMP
WHERE assignment.tenant_id = 123
  AND assignment.deleted = false
  AND (assignment.model_id, assignment.field_code) IN (
      (2595, 'F-f37cd202f4da46558cf5a48a05fd0a4a'),
      (2593, 'F-ab068b1dd098457cba93ad89cf095f90'),
      (2595, 'F-ab068b1dd098457cba93ad89cf095f90'),
      (2593, 'F-0f1f5c4d0e6d4cdd84733f17637a9c04'),
      (2595, 'F-0f1f5c4d0e6d4cdd84733f17637a9c04')
  );

UPDATE dynamicbusiness.dynamic_field field
SET deleted = true,
    updater = 'point-table-seed',
    update_time = CURRENT_TIMESTAMP
WHERE field.tenant_id = 123
  AND field.deleted = false
  AND field.code = 'F-0f1f5c4d0e6d4cdd84733f17637a9c04'
  AND NOT EXISTS (
      SELECT 1 FROM dynamicbusiness.dynamic_model_field_assignment assignment
      WHERE assignment.tenant_id = 123 AND assignment.deleted = false
        AND assignment.field_id = field.id
  )
  AND NOT EXISTS (
      SELECT 1 FROM dynamicbusiness.ent_point_binding_t123 point
      WHERE point.tenant_id = 123 AND point.deleted = false
        AND point.point_field_code = field.code
  );

UPDATE dynamicbusiness.dynamic_field field
SET description = copy.description,
    updater = 'point-table-seed',
    update_time = CURRENT_TIMESTAMP
FROM (VALUES
    ('F-f37cd202f4da46558cf5a48a05fd0a4a', '处于远程时为 1，平台可以控制。为 0 时不在远程，平台不能控制。这是状态，不是开关命令。'),
    ('F-4520018a74e7466aa5d84e4cec521cb7', '处于远程时为 1，平台可以控制。为 0 时不在远程，平台不能控制。这是状态，不是开关命令。'),
    ('F-301fc454fb294c8ba3a1deebeecfe0ee', '为 1 时设备正在运行。为 0 时没有运行。这是状态，不是开关命令。'),
    ('F-8aab1aedc76b4ceb8be9dec26b572ad9', '为 1 时灯已经点亮。为 0 时灯没有点亮。这是状态，不是开关命令。'),
    ('F-0c2239bb2c50496a8b802d4c55e31df5', '为 1 时设备处于故障。为 0 时没有故障。这是状态，不是开关命令。'),
    ('F-614f06636e414cfa9a2781722ccd3e71', '为 1 时处于急停。为 0 时没有急停。这是状态，不是开关命令。'),
    ('F-78a512c0da09423ebc9f31978485363d', '为 1 时井盖已经开到位。为 0 时还没开到位。这是状态，不是开关命令。'),
    ('F-54eb0a20f73142e68caec284889f4ecc', '为 1 时井盖已经关到位。为 0 时还没关到位。这是状态，不是开关命令。'),
    ('F-acb4067e851b4210aa5c58fe4df5f915', '为 1 时报警。为 0 时没有报警。这是报警信号，不是水位数值。'),
    ('F-7bdb03e028f049579dbee3ce64f58365', '为 1 时报警。为 0 时没有报警。这是报警信号，不是水位数值。'),
    ('F-ba04ffdb8a274188b2e30f74791771f9', '为 1 时报警。为 0 时没有报警。这是报警信号，不是水位数值。'),
    ('F-ab068b1dd098457cba93ad89cf095f90', '打开时这个标签保持为 1。关闭时把同一个标签写成 0。没有另一个关标签。')
) AS copy(code, description)
WHERE field.tenant_id = 123
  AND field.deleted = false
  AND field.code = copy.code
  AND field.description IS DISTINCT FROM copy.description;

