INSERT INTO dynamicbusiness.dynamic_entity_category_relation_t123 (
    entity_id, category_id, entity_type_code, sort, creator, updater,
    deleted, tenant_id, domain
)
SELECT
    point.id,
    cabin.id,
    'point_binding',
    zone_link.sort,
    'point-table-seed',
    'point-table-seed',
    false,
    123,
    zone_link.domain
FROM dynamicbusiness.ent_point_binding_t123 point
JOIN point_cabin map
  ON map.zone_code = point.zone_code AND map.tag_name = point.tag_name
JOIN dynamicbusiness.dynamic_entity_category_relation_t123 zone_link
  ON zone_link.entity_id = point.id
 AND zone_link.tenant_id = 123
 AND zone_link.deleted = false
 AND zone_link.entity_type_code = 'point_binding'
JOIN dynamicbusiness.dynamic_category zone_cat
  ON zone_cat.id = zone_link.category_id
 AND zone_cat.tenant_id = 123
 AND zone_cat.deleted = false
 AND zone_cat.level = 4
JOIN dynamicbusiness.dynamic_category cabin
  ON cabin.parent_id = zone_cat.id
 AND cabin.tenant_id = 123
 AND cabin.deleted = false
 AND cabin.level = 5
 AND cabin.name = map.cabin_name
WHERE point.tenant_id = 123
  AND point.deleted = false
  AND NOT EXISTS (
      SELECT 1 FROM dynamicbusiness.dynamic_entity_category_relation_t123 existing
      WHERE existing.tenant_id = 123
        AND existing.entity_type_code = 'point_binding'
        AND existing.entity_id = point.id
        AND existing.category_id = cabin.id
  );

UPDATE dynamicbusiness.dynamic_entity_category_relation_t123 zone_link
SET deleted = true,
    updater = 'point-table-seed',
    update_time = CURRENT_TIMESTAMP
FROM dynamicbusiness.ent_point_binding_t123 point
JOIN point_cabin map
  ON map.zone_code = point.zone_code AND map.tag_name = point.tag_name
JOIN dynamicbusiness.dynamic_category zone_cat
  ON zone_cat.tenant_id = 123 AND zone_cat.deleted = false AND zone_cat.level = 4
WHERE zone_link.entity_id = point.id
  AND zone_link.category_id = zone_cat.id
  AND zone_link.tenant_id = 123
  AND zone_link.deleted = false
  AND zone_link.entity_type_code = 'point_binding'
  AND point.tenant_id = 123
  AND point.deleted = false
  AND EXISTS (
      SELECT 1
      FROM dynamicbusiness.dynamic_entity_category_relation_t123 cabin_link
      JOIN dynamicbusiness.dynamic_category cabin
        ON cabin.id = cabin_link.category_id
       AND cabin.level = 5
       AND cabin.deleted = false
       AND cabin.parent_id = zone_cat.id
       AND cabin.name = map.cabin_name
      WHERE cabin_link.tenant_id = 123
        AND cabin_link.deleted = false
        AND cabin_link.entity_type_code = 'point_binding'
        AND cabin_link.entity_id = point.id
  );

INSERT INTO dynamicbusiness.dynamic_model_category_relation_t123 (
    model_id, category_id, entity_type_code, sort, creator, updater, deleted, tenant_id,
    model_code, category_code
)
SELECT DISTINCT
    model.id,
    category_row.id,
    'point_binding',
    CASE model.code WHEN 'MODEL-point-binding' THEN 10 ELSE 20 END,
    'point-table-seed',
    'point-table-seed',
    false,
    123,
    model.code,
    category_row.code
FROM dynamicbusiness.ent_point_binding_t123 point
JOIN dynamicbusiness.dynamic_model model
  ON model.id = point.model_id AND model.deleted = false
JOIN dynamicbusiness.dynamic_entity_category_relation_t123 entity_link
  ON entity_link.tenant_id = 123
 AND entity_link.deleted = false
 AND entity_link.entity_type_code = 'point_binding'
 AND entity_link.entity_id = point.id
JOIN dynamicbusiness.dynamic_category category_row
  ON category_row.id = entity_link.category_id
 AND category_row.tenant_id = 123
 AND category_row.deleted = false
 AND category_row.category_type_code = 'zone'
WHERE point.tenant_id = 123
  AND point.deleted = false
  AND NOT EXISTS (
      SELECT 1 FROM dynamicbusiness.dynamic_model_category_relation_t123 existing
      WHERE existing.tenant_id = 123
        AND existing.deleted = false
        AND existing.model_id = model.id
        AND existing.category_id = category_row.id
  );

UPDATE dynamicbusiness.dynamic_model_category_relation_t123 link
SET deleted = true,
    updater = 'point-table-seed',
    update_time = CURRENT_TIMESTAMP
FROM dynamicbusiness.dynamic_category category_row
WHERE link.tenant_id = 123
  AND link.deleted = false
  AND link.creator = 'point-table-seed'
  AND link.entity_type_code = 'point_binding'
  AND category_row.id = link.category_id
  AND category_row.category_type_code = 'zone'
  AND category_row.level IN (4, 5)
  AND NOT EXISTS (
      SELECT 1
      FROM dynamicbusiness.ent_point_binding_t123 point
      JOIN dynamicbusiness.dynamic_entity_category_relation_t123 entity_link
        ON entity_link.entity_id = point.id
       AND entity_link.tenant_id = 123
       AND entity_link.deleted = false
       AND entity_link.entity_type_code = 'point_binding'
       AND entity_link.category_id = link.category_id
      WHERE point.tenant_id = 123
        AND point.deleted = false
        AND point.model_id = link.model_id
  );

DO $$
DECLARE
    manhole_remote_wrong integer;
    fan_open_wrong integer;
    cabin_points integer;
    zone_points integer;
    bad_code integer;
    kept_close integer;
BEGIN
    SELECT count(*) INTO manhole_remote_wrong
    FROM dynamicbusiness.ent_point_binding_t123 point
    JOIN dynamicbusiness.ent_equipment_t123 equipment ON equipment.id = point.equipment_id
    WHERE point.tenant_id = 123 AND point.deleted = false
      AND equipment.model_id = 2595
      AND point.tag_name ~ '_I_REMOTE$'
      AND point.point_field_code IS DISTINCT FROM 'F-a11c0e0000014e0a8f0e00000000c001';

    SELECT count(*) INTO fan_open_wrong
    FROM dynamicbusiness.ent_point_binding_t123 point
    JOIN dynamicbusiness.ent_equipment_t123 equipment ON equipment.id = point.equipment_id
    WHERE point.tenant_id = 123 AND point.deleted = false
      AND equipment.model_id = 2593
      AND point.tag_name ~ '_PT_OPEN$'
      AND point.point_field_code IS DISTINCT FROM 'F-a11c0e0000014e0a8f0e00000000c002';

    SELECT count(*) INTO cabin_points
    FROM dynamicbusiness.ent_point_binding_t123 point
    JOIN dynamicbusiness.dynamic_entity_category_relation_t123 link
      ON link.entity_id = point.id AND link.tenant_id = 123 AND link.deleted = false
     AND link.entity_type_code = 'point_binding'
    JOIN dynamicbusiness.dynamic_category category_row
      ON category_row.id = link.category_id AND category_row.level = 5 AND category_row.deleted = false
    WHERE point.tenant_id = 123 AND point.deleted = false;

    SELECT count(*) INTO zone_points
    FROM dynamicbusiness.ent_point_binding_t123 point
    JOIN dynamicbusiness.dynamic_entity_category_relation_t123 link
      ON link.entity_id = point.id AND link.tenant_id = 123 AND link.deleted = false
     AND link.entity_type_code = 'point_binding'
    JOIN dynamicbusiness.dynamic_category category_row
      ON category_row.id = link.category_id AND category_row.level = 4 AND category_row.deleted = false
    WHERE point.tenant_id = 123 AND point.deleted = false;

    SELECT count(*) INTO bad_code
    FROM dynamicbusiness.ent_point_binding_t123 point
    WHERE point.tenant_id = 123 AND point.deleted = false
      AND point.code IS DISTINCT FROM point.zone_code || '/' || point.tag_name;

    SELECT count(*) INTO kept_close
    FROM dynamicbusiness.ent_point_binding_t123 point
    JOIN dynamicbusiness.ent_equipment_t123 equipment ON equipment.id = point.equipment_id
    WHERE point.tenant_id = 123 AND point.deleted = false
      AND equipment.model_id IN (2593, 2595)
      AND point.tag_name ~ '_PT_CLOSE$';

    IF manhole_remote_wrong <> 0 OR fan_open_wrong <> 0 OR cabin_points <> 3969
       OR zone_points <> 1049 OR bad_code <> 0 OR kept_close = 0 THEN
        RAISE EXCEPTION
            'signal cabin adjust failed manhole_remote=% fan_open=% cabin=% zone=% bad_code=% kept_close=%',
            manhole_remote_wrong, fan_open_wrong, cabin_points, zone_points, bad_code, kept_close;
    END IF;
END $$;
